-- Table structure for nightly_check_items
-- ----------------------------
DROP TABLE IF EXISTS `nightly_check_items`;
CREATE TABLE `nightly_check_items`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `nightly_check_id` bigint UNSIGNED NOT NULL,
  `medicine_id` bigint UNSIGNED NOT NULL,
  `code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `quantity` int UNSIGNED NULL DEFAULT NULL,
  `is_low` tinyint(1) NOT NULL DEFAULT 0,
  `requested_quantity` int UNSIGNED NULL DEFAULT NULL,
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `nightly_check_items_nightly_check_id_medicine_id_unique`(`nightly_check_id` ASC, `medicine_id` ASC) USING BTREE,
  INDEX `nightly_check_items_medicine_id_foreign`(`medicine_id` ASC) USING BTREE,
  CONSTRAINT `nightly_check_items_medicine_id_foreign` FOREIGN KEY (`medicine_id`) REFERENCES `medicines` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `nightly_check_items_nightly_check_id_foreign` FOREIGN KEY (`nightly_check_id`) REFERENCES `nightly_checks` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 172 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

